# Focus on the actual electrical panels (not conduits)
main_electrical_panels = []

# Filter out conduits and focus on actual panels
for element in potential_panels:
    if element.is_a() == "IfcFlowTerminal" and ("panelboard" in element.Name.lower() or "panel" in element.Name.lower()):
        main_electrical_panels.append(element)

print("Main Electrical Panels Found:")
print("=" * 50)

for i, panel in enumerate(main_electrical_panels, 1):
    print(f"\n{i}. {panel.Name}")
    print(f"   Type: {panel.is_a()}")
    print(f"   GlobalId: {panel.GlobalId}")

    # Get detailed location information
    spatial_containers = []
    space_info = ""
    building_info = ""

    for rel in ifc_file.by_type("IfcRelContainedInSpatialStructure"):
        if panel in rel.RelatedElements:
            container = rel.RelatingStructure
            if container.is_a() == "IfcSpace":
                space_info = f"Space: {container.Name}"
            elif container.is_a() == "IfcBuildingStorey":
                building_info = f"Floor: {container.Name}"
            elif container.is_a() == "IfcBuilding":
                building_info = f"Building: {container.Name}"

    if space_info:
        print(f"   Location: {space_info}")
    if building_info:
        print(f"   Floor/Building: {building_info}")

    # Try to get additional property information
    try:
        properties = ifcopenshell.util.element.get_psets(panel)
        if properties:
            for pset_name, pset_props in properties.items():
                if any(key.lower() in ['location', 'room', 'space', 'level'] for key in pset_props.keys()):
                    print(f"   Additional Info: {pset_name} - {pset_props}")
    except:
        pass

# Also look for any main distribution equipment
print("\n\nOther Electrical Equipment:")
print("=" * 30)

for element in potential_panels:
    if "fire alarm" in element.Name.lower() or "telephone" in element.Name.lower():
